<?php $fmt=function($v){return rtrim(rtrim(number_format((float)$v,3,',','.'),'0'),',');};$e=function($key)use($s){return html_escape($s[$key]??'');};$days=array('Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu');$dateLabel=function($date)use($days){$months=array(1=>'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember');$t=strtotime($date);return $days[(int)date('w',$t)].', '.date('d',$t).' '.$months[(int)date('n',$t)].' '.date('Y',$t);};$logo=!empty($pdf_mode)?str_replace('\\','/',FCPATH).'assets/images/bunker/asdp-logo.png':base_url('assets/images/bunker/asdp-logo.png');$kind=$row['Kind'];$proof=$proof??array();$pdf_mode=$pdf_mode??false;
$sign=function($field)use($s,$proof,$pdf_mode){
    if (empty($proof[$field])) return html_escape($s[$field]??'');
    $p=$proof[$field];
    $image='<img width="104" height="104" alt="QR approval" src="'.html_escape($p['png']).'">';
    return ($pdf_mode?$image:'<a href="'.html_escape($p['url']).'">'.$image.'</a>').'<br>'.html_escape($p['name']);
}; ?>
